// Staged here until the Android project exists: `src-tauri/gen/android` is generated by `tauri android init`, and this
// file's FLAG_SECURE line goes into the generated `MainActivity.kt` (docs/engineering/data-layer.md, "The Android
// checklist"). If the generated activity carries more than this one (for example `enableEdgeToEdge()`), merge the
// `window.addFlags` line into its `onCreate` after `super.onCreate` rather than replacing the file. The `package`
// line follows the Android namespace, as `EdenDbKey.kt`'s does.
package com.palekodama.eden

import android.os.Bundle
import android.view.WindowManager

/**
 * The main activity, with the window marked secure, always: Recents shows a blank card, and screenshots and screen
 * recordings of Eden are blocked. This is Android's privacy cover; the phone lock itself is the web layer's.
 */
class MainActivity : TauriActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        window.addFlags(WindowManager.LayoutParams.FLAG_SECURE)
    }
}
